def level_order_brute(root):
    if root is None:
        return []
    levels = {}
    def dfs(node, depth):
        if node is None:
            return
        levels.setdefault(depth, []).append(node.val)     # grouped by depth, filled in DFS order
        dfs(node.left, depth + 1)
        dfs(node.right, depth + 1)
    dfs(root, 0)
    return [levels[d] for d in sorted(levels)]

